const $=id=>document.getElementById(id),fields=['insurerParty','policyRef','termsVersion','currency','scale','deductible','incidentLimit','annualLimit','exclusionsRef'];let generation=0,loaded=null,busy=false;const keys=new Map();
function clear(){generation++;loaded=null;$('current').textContent='';$('history').textContent='';$('handoffId').value='';$('exportId').value='';$('disclosure').checked=false;for(const id of [...fields,'numerator','denominator','confirmationEvidence'])$(id).value='';$('mode').value='none';}
async function request(path,options={}){const token=sessionStorage.getItem('incident-session');if(!token)throw Error('请先登录');const response=await fetch('/api/incidents-v1'+path,{...options,headers:{authorization:'Bearer '+token,...(options.body?{'content-type':'application/json'}:{}),...(options.key?{'idempotency-key':options.key}:{})}});if(!response.ok){if(response.status===401){sessionStorage.removeItem('incident-session');clear();}throw Error((await response.json()).error);}return response;}
async function guard(fn){if(busy)return;busy=true;try{await fn();}catch(e){$('status').textContent=e.message;}finally{busy=false;}}
async function write(path,method,body){const serialized=JSON.stringify(body),identity=sessionStorage.getItem('incident-session')+method+path+serialized,key=keys.get(identity)??crypto.randomUUID();keys.set(identity,key);return (await request(path,{method,body:serialized,key})).json();}
const scope=()=>({project:$('project').value,incident:$('incident').value});
async function load(){const selected=scope();clear();const epoch=generation;const result=await (await request(`/incidents/${encodeURIComponent(selected.incident)}/coverage?projectId=${encodeURIComponent(selected.project)}`)).json();if(epoch!==generation)return;loaded={...selected,version:result.current.version};$('current').textContent=JSON.stringify(result.current,null,2);$('history').textContent=JSON.stringify(result.history,null,2);const coverage=result.current.coverage;$('mode').value=coverage.mode;for(const field of fields)$(field).value=coverage[field]??'';$('numerator').value=coverage.share?.numerator??'';$('denominator').value=coverage.share?.denominator??'';$('confirmationEvidence').value=coverage.confirmationEvidence.join('\n');sessionStorage.setItem('coverage-last',JSON.stringify(selected));$('status').textContent=`当前保障版本 ${loaded.version}；外部真实性未经系统核验`;}
function selected(){const now=scope();if(!loaded||loaded.project!==now.project||loaded.incident!==now.incident)throw Error('请先读取当前登记');return loaded;}
$('load').onsubmit=e=>{e.preventDefault();guard(load);};
$('register').onsubmit=e=>{e.preventDefault();guard(async()=>{const context=selected(),epoch=generation,coverage={mode:$('mode').value};for(const field of fields)coverage[field]=$(field).value.trim()||null;coverage.scale=coverage.scale===null?null:Number(coverage.scale);const numerator=$('numerator').value.trim(),denominator=$('denominator').value.trim();coverage.share=numerator||denominator?{numerator,denominator}:null;coverage.confirmationEvidence=$('confirmationEvidence').value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);await write(`/incidents/${encodeURIComponent(context.incident)}/coverage`,'PUT',{projectId:context.project,expectedVersion:context.version,coverage});if(epoch===generation)await load();});};
$('handoff').onsubmit=e=>{e.preventDefault();guard(async()=>{const context=selected(),epoch=generation;const result=await write(`/incidents/${encodeURIComponent(context.incident)}/underwriting-handoffs`,'POST',{projectId:context.project,expectedCoverageVersion:context.version,exportId:$('exportId').value,disclosureAccepted:$('disclosure').checked});if(epoch!==generation)return;$('handoffId').value=result.handoffId;$('status').textContent=`交接包已准备，未发送；有效期至 ${result.expiresAt}`;});};
$('download').onsubmit=e=>{e.preventDefault();guard(async()=>{const epoch=generation,id=$('handoffId').value,response=await request(`/underwriting-handoffs/${encodeURIComponent(id)}?projectId=${encodeURIComponent($('project').value)}`),blob=await response.blob();if(epoch!==generation)return;const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`underwriting-${id}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='已鉴权下载；尚未向任何外部机构发送';});};
for(const id of ['project','incident'])$(id).oninput=()=>{clear();sessionStorage.removeItem('coverage-last');};
$('logout').onclick=()=>guard(async()=>{try{await request('/session',{method:'DELETE'});}finally{sessionStorage.removeItem('incident-session');sessionStorage.removeItem('coverage-last');keys.clear();clear();$('status').textContent='已退出';}});
$('project').value=sessionStorage.getItem('incident-project')||'';try{const saved=JSON.parse(sessionStorage.getItem('coverage-last')||'null');if(saved&&sessionStorage.getItem('incident-session')){$('project').value=saved.project;$('incident').value=saved.incident;guard(load);}}catch{sessionStorage.removeItem('coverage-last');}


